Word server_run_004b6270(Memory&m,RunPorts&p,Word self,Word scratch){p.empty(scratch+8);if(m.read16(self+0x10008)!=1){p.destroy(scratch+8);return 0;}Word messages=m.read(self+0x10010);m.write16(self+0x10008,2);p.player_status(messages,m.read(0x74c52c));Word recipient=m.read(0x74c534);p.admin_status(m.read(self+0x10010),recipient);Word node=m.read(m.read(m.read(self+0x10064)));m.write(scratch+4,node);while(node){Word player=p.at(m.read(m.read(self+0x10064)),node);if(m.read8(player+0x24))p.login_player(self,player);p.next(m.read(m.read(self+0x10064)),scratch+4);node=m.read(scratch+4);}Word module=p.module(self);if(m.read(module+0x1c8)&&m.read(self+0x1007c)!=1){Word list=m.read(self+0x10064);Word head=m.read(m.read(list));m.write(scratch+4,head);Word player=p.at(m.read(list),head);p.select_player(self,player);p.party_ready(self+0x1b770);}if(m.read(self+0x1007c)==1){Word message=p.messages(m.read(m.read(0x7a39fc)+8));p.begin_game(message,1);m.write(self+0x1007c,0);}p.destroy(scratch+8);return 1;}
